/// Quicksort implementation in Rust.
///
/// This function sorts a mutable slice of elements that implement `Ord`
/// using the quicksort algorithm with Lomuto partition scheme.
///
/// # Arguments
/// * `arr` - A mutable slice of elements to be sorted in place.
///
/// # Examples
/// ```
/// let mut data = vec![3, 6, 8, 10, 1, 2, 1];
/// quicksort(&mut data);
/// assert_eq!(data, vec![1, 1, 2, 3, 6, 8, 10]);
/// ```
pub fn quicksort<T: Ord>(arr: &mut [T]) {
    // Base case: slices of length 0 or 1 are already sorted
    if arr.len() <= 1 {
        return;
    }

    // Choose a pivot and partition the array around it.
    // The pivot index is returned after partitioning.
    let pivot_index = partition(arr);

    // Recursively sort the left partition (elements less than pivot)
    quicksort(&mut arr[..pivot_index]);

